def call_tool(name: str, arguments: dict[str, Any]) -> dict[str, Any]:
    handlers: dict[str, Callable[..., dict[str, Any]]] = {
        "controller_start": controller.start,
        "controller_respond": controller.respond,
        "controller_status": controller.status,
        "controller_receipt": controller.receipt,
    }
    if name not in handlers:
        raise ValueError(f"unknown tool: {name}")
    structured = handlers[name](**arguments)
    return {
        "content": [{"type": "text", "text": json.dumps(structured, ensure_ascii=False)}],
        "structuredContent": structured,
        "isError": False,
    }

def dispatch(message: dict[str, Any]) -> None:
    method = message.get("method")
    request_id = message.get("id")
    params = message.get("params") or {}
    if request_id is None:
        return
    try:
        if method == "initialize":
            result(
                request_id,
                {
                    "protocolVersion": PROTOCOL_VERSION,
                    "capabilities": {"tools": {"listChanged": False}},
                    "serverInfo": SERVER_INFO,
                },
            )
        elif method == "ping":
            result(request_id, {})
        elif method == "tools/list":
            result(request_id, {"tools": TOOLS})
        elif method == "tools/call":
            result(request_id, call_tool(params.get("name", ""), params.get("arguments") or {}))
        else:
            error(request_id, -32601, f"method not found: {method}")
    except (TypeError, ValueError) as exc:
        error(request_id, -32602, str(exc))
    except Exception as exc:
        print(f"controller server error: {exc}", file=sys.stderr, flush=True)
        error(request_id, -32603, "internal controller error")

class Controller:
    """Deterministic instruction, validation, and receipt controller."""

    def __init__(self, receipt_dir: Path | None = None) -> None:
        self.transactions: dict[str, Transaction] = {}
        self.receipt_dir = receipt_dir or self._default_receipt_dir()

    def start(self, desired_state: str) -> dict[str, Any]:
        if not isinstance(desired_state, str) or not desired_state.strip():
            raise ValueError("desired_state must be a non-empty string")
        transaction_id = str(uuid.uuid4())
        transaction = Transaction(transaction_id, desired_state.strip())
        self.transactions[transaction_id] = transaction
        request = self._request(
            transaction,
            "Create a list of questions q1 that would assist a solver such as yourself in meeting "
            "the desired state. Return only the required return schema.",
            {"q1": ["<question>"]},
        )
        self._save(transaction)
        return {"transaction_id": transaction_id, **request}

    def respond(self, transaction_id: str, response: dict[str, Any]) -> dict[str, Any]:
        transaction = self._require(transaction_id)
        if not isinstance(response, dict):
            return self._reject(transaction, "response must be a JSON object")

        if transaction.phase == "questions":
            error = self._validate_questions(response)
            if error:
                return self._reject(transaction, error)
            self._record(transaction, "stdin", response)
            transaction.questions = response["q1"]
            if transaction.questions:
                transaction.phase = "answers"
                result = self._ask_current_question(transaction)
            else:
                result = self._ask_for_script(transaction)
        elif transaction.phase == "answers":
            error = self._validate_answer(response)
            if error:
                return self._reject(transaction, error)
            self._record(transaction, "stdin", response)
            question = transaction.questions[transaction.question_index]
            transaction.answers.append({"question": question, "answer": response["answer"]})
            transaction.question_index += 1
            if transaction.question_index < len(transaction.questions):
                result = self._ask_current_question(transaction)
            else:
                result = self._ask_for_script(transaction)
        elif transaction.phase == "script":
            error = self._validate_script(response)
            if error:
                return self._reject(transaction, error)
            self._record(transaction, "stdin", response)
            transaction.script = response["script"]
            transaction.phase = "complete"
            result = {
                "transaction_id": transaction_id,
                "status": "complete",
                "message": "Thanks, that completes the interrogation.",
                "script": transaction.script,
                "execution": "not_run",
            }
            self._record(transaction, "stdout", result)
        else:
            raise ValueError("transaction is already complete")

        self._save(transaction)
        return result

    def status(self, transaction_id: str) -> dict[str, Any]:
        transaction = self._require(transaction_id)
        return {
            "transaction_id": transaction.transaction_id,
            "desired_state": transaction.desired_state,
            "phase": transaction.phase,
            "question_index": transaction.question_index,
            "question_count": len(transaction.questions),
            "complete": transaction.phase == "complete",
        }

    def receipt(self, transaction_id: str) -> dict[str, Any]:
        return asdict(self._require(transaction_id))

    def _ask_current_question(self, transaction: Transaction) -> dict[str, Any]:
        return {
            "transaction_id": transaction.transaction_id,
            **self._request(
                transaction,
                transaction.questions[transaction.question_index],
                {"answer": "<answer>"},
            ),
        }

    def _ask_for_script(self, transaction: Transaction) -> dict[str, Any]:
        transaction.phase = "script"
        request = {
            "instruction": "Return a script using qa1 as the context parameter. Return only the required return schema.",
            "qa1": transaction.answers,
            "return_schema": {"script": "<script>"},
        }
        self._record(transaction, "stdout", request)
        return {"transaction_id": transaction.transaction_id, **request}

    def _request(self, transaction: Transaction, instruction: str, schema: dict[str, Any]) -> dict[str, Any]:
        request = {"instruction": instruction, "return_schema": schema}
        self._record(transaction, "stdout", request)
        return request

    def _reject(self, transaction: Transaction, error: str) -> dict[str, Any]:
        previous = next(event["data"] for event in reversed(transaction.events) if event["stream"] == "stdout")
        result = {"error": error, "repeat": previous}
        self._record(transaction, "validation", result)
        self._save(transaction)
        return result

    @staticmethod
    def _validate_questions(value: dict[str, Any]) -> str | None:
        if set(value) != {"q1"}:
            return "response keys must be exactly ['q1']"
        if not isinstance(value["q1"], list) or not all(isinstance(q, str) for q in value["q1"]):
            return "q1 must be a JSON array of strings"
        return None

    @staticmethod
    def _validate_answer(value: dict[str, Any]) -> str | None:
        if set(value) != {"answer"}:
            return "response keys must be exactly ['answer']"
        return None if isinstance(value["answer"], str) else "answer must be a string"

    @staticmethod
    def _validate_script(value: dict[str, Any]) -> str | None:
        if set(value) != {"script"}:
            return "response keys must be exactly ['script']"
        return None if isinstance(value["script"], str) else "script must be a string"

    def _require(self, transaction_id: str) -> Transaction:
        try:
            return self.transactions[transaction_id]
        except KeyError:
            raise ValueError("unknown transaction_id") from None

    @staticmethod
    def _record(transaction: Transaction, stream: str, data: dict[str, Any]) -> None:
        transaction.events.append({"sequence": len(transaction.events), "stream": stream, "data": data})

    def _save(self, transaction: Transaction) -> None:
        self.receipt_dir.mkdir(parents=True, exist_ok=True)
        path = self.receipt_dir / f"{transaction.transaction_id}.json"
        temporary = path.with_suffix(".tmp")
        temporary.write_text(json.dumps(asdict(transaction), ensure_ascii=False, indent=2), encoding="utf-8")
        temporary.replace(path)

    @staticmethod
    def _default_receipt_dir() -> Path:
        override = os.environ.get("ECC_DATA_DIR")
        if override:
            return Path(override)
        local_app_data = os.environ.get("LOCALAPPDATA")
        if local_app_data:
            return Path(local_app_data) / "ExecutionContractController" / "receipts"
        return Path.home() / ".execution-contract-controller" / "receipts"

class RetrievalAdapter(Protocol):
    """Future Solver/KB adapters implement exactly this local Python interface."""

    adapter_id: str

    def retrieve_context(self, query: str, limit: int = 52) -> RetrievalResult | Mapping[str, Any]:
        ...

class RetrievalService:
    """Single fail-open normalization boundary shared by MIS and public tool calls."""

    def __init__(self, adapter: RetrievalAdapter | None = None):
        self.adapter: RetrievalAdapter = adapter or NullRetrievalAdapter()

    def set_adapter(self, adapter: RetrievalAdapter | None) -> None:
        self.adapter = adapter or NullRetrievalAdapter()

    def retrieve(self, query: str, limit: int = 52) -> RetrievalResult:
        if not isinstance(query, str) or not query.strip():
            raise ValueError("query must be a non-empty string")
        if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1 or limit > 52:
            raise ValueError("limit must be an integer from 1 to 52")

        adapter_id = str(getattr(self.adapter, "adapter_id", self.adapter.__class__.__name__))
        try:
            raw = self.adapter.retrieve_context(query, limit)
            return self._normalize(query, raw, adapter_id)
        except Exception as exc:  # Retrieval must not prevent a transaction from starting.
            return RetrievalResult(
                query=query,
                matches=[],
                status="error",
                adapter_id=adapter_id,
                provenance={},
                error=f"{exc.__class__.__name__}: {exc}",
            )

    @staticmethod
    def _normalize(
        query: str,
        raw: RetrievalResult | Mapping[str, Any],
        fallback_adapter_id: str,
    ) -> RetrievalResult:
        if isinstance(raw, RetrievalResult):
            candidate = raw.to_dict()
        elif isinstance(raw, Mapping):
            candidate = dict(raw)
        else:
            raise TypeError("adapter result must be RetrievalResult or mapping")

        matches = candidate.get("matches", [])
        if not isinstance(matches, list) or not all(isinstance(item, Mapping) for item in matches):
            raise TypeError("adapter result 'matches' must be a list of mappings")

        provenance = candidate.get("provenance", {})
        if provenance is None:
            provenance = {}
        if not isinstance(provenance, Mapping):
            raise TypeError("adapter result 'provenance' must be a mapping")

        status = candidate.get("status", "ok")
        if status not in {"ok", "error"}:
            raise ValueError("adapter result 'status' must be 'ok' or 'error'")

        error = candidate.get("error")
        if error is not None and not isinstance(error, str):
            raise TypeError("adapter result 'error' must be a string or null")

        return RetrievalResult(
            query=query,
            matches=[copy.deepcopy(dict(item)) for item in matches],
            status=status,
            adapter_id=str(candidate.get("adapter_id") or fallback_adapter_id),
            provenance=copy.deepcopy(dict(provenance)),
            error=error,
        )

def _score_records(query: str, records: list[dict[str, Any]], cfg: dict[str, Any]) -> list[tuple[float,dict[str,Any]]]:
    qset=set(_tokens(query))
    docs={}; df={}
    for r in records:
        toks=_tokens(_record_search_text(r)); docs[r["id"]]=toks
        for tok in set(toks): df[tok]=df.get(tok,0)+1
    n=len(records); avgdl=sum(map(len,docs.values()))/max(n,1)
    priors=cfg.get("type_prior",{}) if isinstance(cfg.get("type_prior"),dict) else {}
    scored=[]; low_query=query.lower()
    for r in records:
        toks=docs[r["id"]]; counts={}
        for tok in toks: counts[tok]=counts.get(tok,0)+1
        score=0.0
        for tok in qset:
            if tok not in counts: continue
            freq=counts[tok]
            idf=math.log(1.0+(n-df.get(tok,0)+0.5)/(df.get(tok,0)+0.5))
            denom=freq+1.2*(1-0.75+0.75*len(toks)/max(avgdl,1.0))
            score += idf*(freq*2.2/denom)
        kid=str(r["id"]).lower()
        if kid in low_query: score += 8.0
        retrieval=r.get("retrieval",{}) if isinstance(r.get("retrieval"),dict) else {}
        aliases=retrieval.get("aliases",[])
        if isinstance(aliases,list):
            for alias in aliases:
                if isinstance(alias,str) and alias.lower() in low_query: score += 4.0
        score *= float(priors.get(r.get("type"),1.0))
        scored.append((score,r))
    return scored

def rank_all_knowledge(query: str, requested_types: list[str]|None=None, kb_path: str|pathlib.Path=KB_PATH) -> dict[str, Any]:
    """Return every selected canonical record sorted by final relevance value ``k``.

    ``k`` is the native BM25-style score plus deterministic exact-id/alias boosts
    and the type prior. One-hop link influence is exposed separately so it cannot
    displace a stronger direct match. Zero-score records remain in the result.
    """
    if not isinstance(query,str) or not query.strip(): raise ValueError("knowledge query must be non-empty")
    kb=load_kb(kb_path)
    cfg=kb.get("retrieval",{}) if isinstance(kb.get("retrieval"),dict) else {}
    types=requested_types or sorted(KNOWLEDGE_TYPES)
    bad=[t for t in types if t not in KNOWLEDGE_TYPES]
    if bad: raise ValueError(f"unknown knowledge types: {bad}")
    records=[r for r in kb["records"] if isinstance(r,dict) and r.get("type") in types]
    base=_score_records(query,records,cfg)
    base_by_id={r["id"]:score for score,r in base}
    bonus_by_id={r["id"]:0.0 for _,r in base}
    linked_from={r["id"]:[] for _,r in base}
    for score,r in base:
        if score <= 0: continue
        for linked_id in _link_ids(r):
            if linked_id in bonus_by_id:
                bonus_by_id[linked_id] += score*0.35
                linked_from[linked_id].append(r["id"])
    ranked=[]
    for _,r in base:
        record_id=r["id"]
        base_score=base_by_id[record_id]
        link_bonus=bonus_by_id[record_id]
        ranked.append({
            "id":record_id,
            "type":r["type"],
            "k":round(base_score,6),
            "score_components":{"base":round(base_score,6),"link_bonus":round(link_bonus,6)},
            "linked_from":sorted(linked_from[record_id]),
            "record":copy.deepcopy(r),
        })
    ranked.sort(key=lambda item:(-item["k"],item["id"]))
    for rank,item in enumerate(ranked,1): item["rank"]=rank
    return {
        "schema":kb.get("schema"),"version":kb.get("version"),
        "epistemic_policy":copy.deepcopy(kb.get("epistemic_policy",{})),
        "query":query,"sort":"k_desc_id_asc","record_count":len(ranked),"records":ranked,
    }

def search_knowledge(query: str, requested_types: list[str]|None=None, top_k: int|None=None, kb_path: str|pathlib.Path=KB_PATH) -> dict[str, Any]:
    """Canonical Solver-KB query recovered from execution_contract_controller.py.

    Ranking: BM25-style token score + exact ID/alias boosts + type priors,
    followed by one-hop linked-record expansion. This is intentionally not the
    unrelated ChatGPT-history NumPy/GloVe query implementation.
    """
    if not isinstance(query,str) or not query.strip(): raise ValueError("knowledge query must be non-empty")
    kb=load_kb(kb_path)
    cfg=kb.get("retrieval",{}) if isinstance(kb.get("retrieval"),dict) else {}
    max_k=int(cfg.get("max_top_k",16)); k=min(max(1,int(top_k or cfg.get("default_top_k",8))),max_k)
    types=requested_types or sorted(KNOWLEDGE_TYPES)
    bad=[t for t in types if t not in KNOWLEDGE_TYPES]
    if bad: raise ValueError(f"unknown knowledge types: {bad}")
    records=[r for r in kb["records"] if isinstance(r,dict) and r.get("type") in types]
    if not records:
        return {"schema":kb.get("schema"),"version":kb.get("version"),
                "epistemic_policy":copy.deepcopy(kb.get("epistemic_policy",{})),
                "query":query,"types":types,"results":[]}
    scored=[item for item in _score_records(query,records,cfg) if item[0]>0]
    scored.sort(key=lambda x:(-x[0],x[1]["id"])); primary=scored[:k]
    by_id={r["id"]:r for r in kb["records"] if isinstance(r,dict) and isinstance(r.get("id"),str)}
    results=[]; seen=set()
    for score,r in primary:
        results.append({"id":r["id"],"type":r["type"],"score":round(score,6),"source":"primary","record":copy.deepcopy(r)})
        seen.add(r["id"])
    for score,r in primary:
        for linked_id in _link_ids(r):
            if linked_id in seen or linked_id not in by_id: continue
            linked=by_id[linked_id]
            results.append({"id":linked_id,"type":linked.get("type"),"score":round(score*0.35,6),"source":f"link:{r['id']}","record":copy.deepcopy(linked)})
            seen.add(linked_id)
            if len(results)>=max_k: break
        if len(results)>=max_k: break
    return {"schema":kb.get("schema"),"version":kb.get("version"),
            "epistemic_policy":copy.deepcopy(kb.get("epistemic_policy",{})),
            "query":query,"types":types,"results":results}

def encode(value: dict) -> str:
    """Return compact URL-safe JSON without padding."""
    raw = json.dumps(value, separators=(",", ":"), sort_keys=True).encode()
    return base64.urlsafe_b64encode(raw).decode().rstrip("=")

def decode(token: str) -> dict:
    """Decode a token and require its address fields."""
    try:
        value = json.loads(base64.urlsafe_b64decode(token + "=" * (-len(token) % 4)))
    except Exception as exc:
        raise ValueError("invalid token") from exc
    missing = REQUIRED - value.keys()
    if missing:
        raise ValueError(f"token missing: {', '.join(sorted(missing))}")
    return value

class DeliveryLedger:
    """Resolve each address once and replay its result until acknowledgement."""

    def __init__(self, runner):
        self.runner = runner
        self.lock = threading.Lock()
        self.pending = {}
        self.consumed = set()
        self.acknowledged = set()
        self.terminals = {}

    def resolve(self, address: str) -> dict:
        """Return one stable pending delivery for an address."""
        with self.lock:
            if address in self.consumed:
                raise AddressConsumed(address)
            if address not in self.pending:
                self.pending[address] = self._create_delivery(address)
            return dict(self.pending[address])

    def acknowledge(self, delivery_id: str) -> dict:
        """Consume an address only after its delivery is acknowledged."""
        with self.lock:
            if delivery_id in self.acknowledged:
                return {"status": "ACKNOWLEDGED", "delivery_id": delivery_id}
            address = self._address_for(delivery_id)
            terminal = self.pending[address].get("terminal")
            self.pending.pop(address)
            if self.terminals.get(str(terminal)) == address:
                self.terminals.pop(str(terminal))
            self.consumed.add(address)
            self.acknowledged.add(delivery_id)
            return {"status": "ACKNOWLEDGED", "delivery_id": delivery_id}

    def publish(self, terminal, result: dict) -> dict:
        """Place one MCP result in a terminal outbox for Apps Script."""
        with self.lock:
            address = "mcp:" + uuid.uuid4().hex
            delivery = self._delivery(address, terminal, result)
            self.pending[address] = delivery
            self.terminals[str(terminal)] = address
            return dict(delivery)

    def latest(self, terminal) -> dict:
        """Return the latest unacknowledged result for one terminal."""
        with self.lock:
            address = self.terminals.get(str(terminal))
            if address is None:
                raise DeliveryNotFound(str(terminal))
            return dict(self.pending[address])

    def _create_delivery(self, address: str) -> dict:
        """Execute one address and package the result for Apps Script."""
        command = decode_request(address)
        result = self.runner.transaction(command["value"], response=command.get("response"), terminal=command.get("terminal"))
        return self._delivery(address, command.get("terminal"), result)

    def _delivery(self, address: str, terminal, result: dict) -> dict:
        """Build one pending delivery shared by push and address flows."""
        delivery_id = hashlib.sha256(address.encode()).hexdigest()[:24]
        return {
            "status": "PENDING_ACK",
            "delivery_id": delivery_id,
            "terminal": terminal,
            "result": result,
            "ack_path": "/ack",
        }

    def _address_for(self, delivery_id: str) -> str:
        """Find the pending address belonging to a delivery identifier."""
        for address, delivery in self.pending.items():
            if delivery["delivery_id"] == delivery_id:
                return address
        raise DeliveryNotFound(delivery_id)

class DefinitionStore:
    """Resolve aliases and versioned scripts from one directory."""
    def __init__(self, root: str | Path):
        self.root = Path(root)
    def alias(self, name: str) -> dict:
        """Return the initial address assigned to an alias."""
        return self._read(self.root / "aliases" / f"{name}.json")
    def catalog(self) -> list:
        """List installed entry aliases whose script and screen resolve."""
        entries = []
        for path in sorted((self.root / "aliases").glob("*.json")):
            address = self._read(path)
            script = self.script(address["script"], address["version"])
            if address["screen"] not in script["screens"]:
                raise LookupError(f"Invalid entry screen for alias: {path.stem}")
            entries.append({"alias": path.stem, "entry": address})
        return entries
    def script(self, name: str, version: int) -> dict:
        """Return one immutable script version."""
        return self._read(self.root / "scripts" / f"{name}.v{version}.json")
    def check_publish(self, script):
        """Validate a new version and reject changes to an existing version."""
        validate_script(script)
        path = self.root / 'scripts' / f"{script['id']}.v{script['version']}.json"
        if path.exists() and self._read(path) != script:
            raise ValueError('This version already exists. Choose a new version; old versions are immutable.')
        return path

    def publish_script(self, script):
        """Create an approved definition, allowing identical delivery retries."""
        path = self.check_publish(script)
        path.parent.mkdir(parents=True, exist_ok=True)
        try:
            with path.open('x', encoding='utf-8') as output:
                json.dump(script, output, indent=2, ensure_ascii=False)
        except FileExistsError:
            if self._read(path) != script:
                raise ValueError('Version already exists with different content.') from None
        return path
    def terminal(self, identifier) -> dict:
        """Return the canonical Sheet location for one terminal."""
        directory = self._read(self.root / "terminals.json")
        key = str(identifier)
        try:
            terminal = dict(directory["terminals"][key])
        except KeyError as exc:
            raise LookupError(f"terminal not found: {key}") from exc
        spreadsheet_id = directory["spreadsheet_id"]
        terminal["id"] = identifier
        terminal["spreadsheet_id"] = spreadsheet_id
        terminal["url"] = (
            f"https://docs.google.com/spreadsheets/d/{spreadsheet_id}/edit"
            f"?gid={terminal['gid']}#gid={terminal['gid']}"
        )
        return terminal
    @staticmethod
    def _read(path: Path) -> dict:
        """Read one JSON object or fail with its exact missing address."""
        if not path.is_file():
            raise LookupError(f"definition not found: {path.name}")
        return json.loads(path.read_text(encoding="utf-8"))

def call_transaction(arguments: dict[str, Any]) -> dict[str, Any]:
    """Route a runtime result to a terminal without exposing it to the agent."""
    if apps_script_mode():
        return forward_to_apps_script(arguments)
    value, terminal = terminal_request(arguments)
    result = RUNNER.transaction(
        value,
        arguments.get("response"),
        terminal,
    )
    result["addresses"] = [
        "/resolve/" + encode_request(command) for command in result["commands"]
    ]
    terminal = result.get("terminal")
    if terminal is None:
        raise ValueError("terminal is required for routed output")
    location = RUNNER.store.terminal(terminal)
    delivery = DELIVERIES.publish(terminal, result)
    try:
        rendered = push_delivery(delivery)
    except Exception:
        return {"content": [{"type": "text", "text": f"Terminal {terminal} update failed; retry the call."}],
                "structuredContent": {"status": "DELIVERY_FAILED", "terminal": terminal,
                                      "terminal_url": location["url"]}, "isError": True}
    TERMINAL_STATE[str(terminal)] = result["in_token"]
    if rendered:
        DELIVERIES.acknowledge(delivery["delivery_id"])
    # The terminal is the sole interaction surface by default. A deployment
    # may opt into a short configured reply without exposing screen data.
    return configured_reply(terminal, location["url"])

def dispatch(message: dict[str, Any]) -> None:
    """Route one supported MCP JSON-RPC request."""
    request_id = message.get("id")
    if request_id is None:
        return
    method = message.get("method")
    params = message.get("params") or {}
    if method == "initialize":
        send_result(request_id, {"protocolVersion": PROTOCOL_VERSION, "capabilities": {"tools": {"listChanged": False}}, "serverInfo": SERVER_INFO})
    elif method == "ping":
        send_result(request_id, {})
    elif method == "tools/list":
        send_result(request_id, {"tools": [TRANSACTION_TOOL]})
    elif method == "tools/call" and params.get("name") == "transaction":
        send_result(request_id, call_transaction(params.get("arguments") or {}))
    else:
        send_error(request_id, -32601, f"method not found: {method}")

def semantic_rank(query, items):
    docs = [Counter(tokens(record_text(r))) for r in items]
    q = Counter(tokens(query))
    n = max(1, len(docs))
    df = Counter(t for d in docs for t in d)
    def vec(c): return {t: f * (math.log((n + 1)/(df[t] + 1)) + 1) for t, f in c.items()}
    qv = vec(q)
    def cosine(d):
        dv = vec(d); dot = sum(qv.get(t,0)*v for t,v in dv.items())
        return dot / ((sum(v*v for v in qv.values())**.5 or 1)*(sum(v*v for v in dv.values())**.5 or 1))
    return sorted(((cosine(d), r) for d, r in zip(docs, items)), key=lambda x: x[0], reverse=True)

def architecture(goal, constraints=''):
    cls = classify(goal); hits = retrieve(goal+' '+constraints, 5)
    families = []
    for h in hits:
        if h['solver_family'] not in families: families.append(h['solver_family'])
    return {
      'problem_representation': cls,
      'evidence': hits,
      'candidate_architectures': [
        {'name':'ontology-guided case synthesis','families':families[:3] or ['retrieval_and_synthesis'],'tradeoff':'Fast and evidence-linked; limited by corpus coverage.'},
        {'name':'fresh model plus adversarial validation','families':['creative_design','verification'],'tradeoff':'Can escape corpus bias; costs more and needs stronger tests.'}
      ],
      'selected_architecture': {
        'stages':['frame exact objective and authority','classify across every ontology perspective','retrieve positive and disconfirming analogies','generate at least two architectures','check assumption and interface compatibility','select and express executable task graph','run mechanical and semantic validation','stop on satisfied gates or explicit impasse'],
        'deterministic_operations':['schema validation','provenance preservation','ID generation','coverage accounting'],
        'semantic_operations':['classification','analogy judgment','architecture composition','adequacy evaluation'],
        'stop_conditions':['all mandatory acceptance tests pass','a required authority or input is unavailable','new evidence no longer changes the selected architecture materially']
      },
      'coverage_gaps':[p for p,v in cls['perspectives'].items() if v['coverage']=='needs-evidence'],
      'warning':'Selection is a defeasible recommendation derived from the current KB, not proof of optimality.'
    }

def call_tool(name, a):
    if name == 'classify_problem': return classify(a['goal'])
    if name == 'retrieve_solver_patterns': return retrieve(a['query'], a.get('limit',5))
    if name == 'design_solver_architecture': return architecture(a['goal'], a.get('constraints',''))
    if name == 'kb_stats':
        rs=records(); return {'records':len(rs),'solver_families':dict(Counter(r.get('solver_family','unknown') for r in rs)),'ontology':ONTOLOGY}
    if name == 'ingest_knowledge':
        r=a['record']; required=['title','problem','solver_family','solver_pattern','source']
        missing=[x for x in required if not r.get(x)]
        if missing: raise ValueError('Missing required fields: '+', '.join(missing))
        r.setdefault('id','kb-'+hashlib.sha256(json.dumps(r,sort_keys=True).encode()).hexdigest()[:16])
        r.setdefault('problem_tags',[]); r.setdefault('applicability',[]); r.setdefault('failure_modes',[]); r.setdefault('validation',[])
        with KB_PATH.open('a',encoding='utf-8') as f: f.write(json.dumps(r,ensure_ascii=False)+'\n')
        return {'ingested':r['id'],'source':r['source']}
    raise ValueError('Unknown tool')
